    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS24R1, self).__init__(api_client)

    def reset_unit(self, dist_name, reset_type='Soft', force_radio_reset=None, timeout=60, detailed_output=False,
                   graceful_cell_shutdown=None):
        """
        Preform unit reset procedure.

        :param dist_name: Dist name of unit to reset which is runtime view dist name like:
                          /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1/GNSSE_R-1.
        :param str reset_type: <Soft, Hard, Warm, PowerReset> (optional - default value for GNSSE, GNSSI, ALD, TTMOD should
                               be Hard, and Warm for BBMOD.
                               It is set as 'Soft' by default due to legacy reasons.
                               Since CB010884-B, resetType with "Warm" and "PowerReset" value are only valid for BBMOD reset.
                               And BBMOD reset can only support warm reset/power reset.
        :param bool force_radio_reset: (Optional) can be set to True or False.
        :param int timeout: Timeout for the operation.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param bool graceful_cell_shutdown: (Optional) - Defaults to False, it is not applicable to ALD/GNSSE/GNSSI.
        :return Union[list,dict]: Unit reset status, or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-reset.html
        """
        if not reset_type == 'PowerReset':
            reset_type = reset_type.title()

        parameters = {"id": dist_name, 'resetType': reset_type}
        if force_radio_reset is not None:
            parameters['forceRadioReset'] = force_radio_reset

        if graceful_cell_shutdown is not None:
            parameters['gracefulCellShutdown'] = graceful_cell_shutdown

        parameters = {k: v for k, v in parameters.items() if v is not None}

        response = self._api_client.execute_customer_procedure("reset", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def get_ssd_wifi_info(self, timeout=60, detailed_output=False):
        """
        Get SSD WiFi information.

        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getSSDWifiInfo.html
        """
        response = self._api_client.execute_customer_procedure("getSSDWifiInfo", {}, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def set_ssd_wifi_user(self, user_file, file_name=None, timeout=60, detailed_output=False):
        """
        Set SSD WiFi user.

        :param str user_file: Mandatory XML file with configured user info.
        :param str file_name: Name of user_file used. Processed internally.
                              Note: 29.11.2023 This parameter is not mentioned, but currently required by WebEM/CLI code.
        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str,dict]: Result operation result as string ie. Completed, Failed, sometimes empty or full response dict.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-setSSDWifiUser.html
        """

        file_name = str(user_file)
        if os.path.isfile(user_file):
            with open(user_file, 'r') as f:
                user_file = f.read()

        six_user_file = six.b(user_file)
        b64_user_file = base64.b64encode(six_user_file)
        parameters = {"inputFileName": file_name, "inputFileContent": b64_user_file.decode("utf-8")}

        response = self._api_client.execute_customer_procedure("setSSDWifiUser", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def add_rat(self, rat_technology, plan_scf_file, rat_scf_file, output_scf, timeout=60, band=None, merge_bts=None):
        """Add RAT technology into given SCF file

        :param string rat_technology: Name of RAT being added. ["GSM"|"WCDMA"|"LTE"|"NR"]. Can also be passed as a list,
        ie: ["GSM", "WCDMA", "LTE", "NR"]
        :param string plan_scf_file: SCF file path with plan configuration.
        :param string rat_scf_file: SCF file path with RAT specific configuration.
        :param string output_scf: Output SCF file path
        :param boolean merge_bts: (optional) Merge BTS.
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :param string band: (optional) Support multiple bands, separated by comma, i.e.: "1,2"
                            (Since RP002551 band supported, it is optional and only supported for LTE and WCDMA)
                            (Since feature CB005878, it supported for NR)
                            (Since CB008999, band will be ignored when there're multi rats or mergeBTS=true')
        :return dict: dict with list of skipped objects.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-addRat.html
        """

        parameters = {"ratTechnology": rat_technology}

        if band is not None:
            parameters["band"] = band
        if merge_bts is not None:
            if not isinstance(merge_bts, bool):
                raise ValueError('Parameter merge_bts should be bool True or False not {}'.format(type(merge_bts)))
            parameters["mergeBTS"] = merge_bts

        skipped_objects = self._api_client.execute_offline_procedure("addRat", parameters, timeout,
                                                                     plan_scf_file=plan_scf_file,
                                                                     rat_scf_file=rat_scf_file,
                                                                     output_file_name=output_scf)

        return skipped_objects

    def interface_mirroring(self, operation, interface=None, destination=None, mirroring_time=None, nr_cell_dns=None, timeout=60,  # noqa: C901
                            detailed_output=False, parallel_mirroring=None, mirroring_filter=None, specific_message_ids=None):

        """
        Interface mirroring

        :param string interface: ["L1-L2"|"L2Hi-L2Lo"] mandatory, operator only configures it for operation 'Start'
        :param string destination: [Local"|"Remote] mandatory, operator only configures it for operation 'Start'
        :param int mirroring_time: [0, 2147483647] seconds mandatory, operator only configures it for operation 'Start'
        :param string operation: ["Start"|"Stop"] mandatory
        :param list nr_cell_dns: optional, operator only configures it for operation 'Start', operator can select up to 8 NR cells
        :param int timeout: Time in seconds to wait for positive procedure result.
        :param bool detailed_output: Return full request response when True, defaults set to False.
        :param bool parallel_mirroring: Optional, only configures it for operation 'Start'. Only available from SBTS23R3 onwards.
        :param string mirroring_filter: Optional, ["Default" | "AllMessages" | "SpecificL1L2Messages"].
                                        Only supported when interface is 'L1-L2' and destination is 'Local'.
                                        Only available from SBTS24R1 onwards.
        :param list specific_message_ids: Optional, only supported when mirroring_filter is 'SpecificL1L2Messages'.
                                          List containing string values. Must be in hex format.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-interfaceMirroring.html
        """

        if operation not in ["Start", "Stop"]:
            raise_value_error(param="operation",
                              value=str(operation),
                              subpage="tutorial-interfaceMirroring.html")

        parameters = {"operation": operation}

        if operation == "Start":
            if parallel_mirroring:
                parameters["parallelL1L2Mirroring"] = parallel_mirroring
            else:
                mirroring_time = int(mirroring_time)
                if interface not in ["L1-L2", "L2Hi-L2Lo"]:
                    raise_value_error(param="interface",
                                      value=str(interface),
                                      subpage="tutorial-interfaceMirroring.html")

                if destination not in ["Local", "Remote"]:
                    raise_value_error(param="destination",
                                      value=str(destination),
                                      subpage="tutorial-interfaceMirroring.html")

                if mirroring_time < 0 or mirroring_time > 2147483647:
                    raise_value_error(param="mirroring_time",
                                      value=str(mirroring_time),
                                      subpage="tutorial-interfaceMirroring.html")

                parameters["interface"] = interface
                parameters["destination"] = destination
                parameters["mirroringTime"] = mirroring_time

                if mirroring_filter:
                    if mirroring_filter not in ["Default", "AllMessages", "SpecificL1L2Messages"]:
                        raise_value_error(param="mirroring_filter",
                                          value=str(mirroring_filter),
                                          subpage="tutorial-interfaceMirroring.html")
                    parameters["l1L2MirroringFilter"] = mirroring_filter

                if specific_message_ids:
                    parameters["specificL1L2MessageIds"] = specific_message_ids

        if nr_cell_dns:
            parameters["nrCellDNs"] = nr_cell_dns

        response = self._api_client.execute_customer_procedure("interfaceMirroring", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def reset_cell(self, cell_id, timeout=60, detailed_output=False, graceful_cell_shutdown=None):
        """
        Cell reset available from 18A.

        :param str cell_id: NRCEL|LNCEL|WNCEL|GNCEL distName
        :param int timeout: (optional) Timeout for the operation. Defaults set to 120s.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :param bool graceful_cell_shutdown: (Optional) - Defaults to False. Available from CB006830.
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.
        :return Union[list,dict]: reset cell feedback info or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-reset.html
        """

        parameters = {"id": cell_id}

        if graceful_cell_shutdown:
            parameters['gracefulCellShutdown'] = graceful_cell_shutdown

        response = self._api_client.execute_customer_procedure(
            name='reset',
            parameters=parameters,
            timeout=timeout)
        if response is None:
            raise DataNotAvailable("ResetCell data has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)

