    def get_parameter_by_distname(self, dist_name, parameter_list=None, include_children=None, timeout=60,
                                  detailed_output=False):
        """
        Get parameter by dist name.

        :param string class_name: Mandatory, desired dist name to be retrieved.
        :param list parameter_list: Optional, list of parameters to be retrieved.
        :param boolean include_children: Optional.
        :param int timeout: Timeout for the operation, 60 second by default.
        :param bool detailed_output: return full request response when True, by default set to False.
        :return list: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getParameterByDN.html
        """
        parameters = {"distName": dist_name}

        if parameter_list is not None:
            parameters["parameterList"] = parameter_list
        if include_children is not None:
            parameters["includeChildren"] = include_children

        response = self._api_client.execute_customer_procedure("getParameterByDN", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)
